"""Fail fast with specific and custom exceptions, and log at the right level.

A model expects exactly 3 features. Three scenarios: clean data, a dimension
mismatch (handled: WARNING + documented fallback), and missing values (ERROR:
halt for this record rather than silently predicting from corrupted data).
"""
import logging, math, sys

logging.basicConfig(stream=sys.stdout, level=logging.INFO,
                    format="%(levelname)-8s %(name)s:%(lineno)d  %(message)s")
log = logging.getLogger("inference")

class IncompatibleFeatureSizeError(ValueError):
    """Raised when the input vector length doesn't match the model."""

class ModelWeightsNotLoadedError(RuntimeError):
    """Raised when predict() is called before weights are loaded."""

class TinyModel:
    N_FEATURES = 3
    def __init__(self): self.weights = None
    def load(self):
        self.weights = [0.5, 1.2, -0.3]; log.info("model loaded with %d weights", len(self.weights))
    def predict(self, x):
        if self.weights is None:
            raise ModelWeightsNotLoadedError("call load() before predict()")
        if len(x) != self.N_FEATURES:
            raise IncompatibleFeatureSizeError(f"expected {self.N_FEATURES} features, got {len(x)}")
        if any(v is None or (isinstance(v, float) and math.isnan(v)) for v in x):
            raise ValueError("input contains missing values (NaN/None)")
        return sum(w * v for w, v in zip(self.weights, x))

def safe_predict(model, x, fallback=0.0):
    try:
        y = model.predict(x); log.info("prediction %.2f", y); return y
    except IncompatibleFeatureSizeError as e:          # recoverable: documented default
        log.warning("%s; returning fallback %.2f", e, fallback); return fallback
    except ValueError as e:                             # data corruption: do not guess
        log.error("data corruption: %s; halting for this record", e); return None

m = TinyModel()
try:
    m.predict([1, 2, 3])
except ModelWeightsNotLoadedError as e:
    log.critical("startup check failed: %s", e)
m.load()
print("scenario 1 ->", safe_predict(m, [2.0, 1.6, 0.2]))
print("scenario 2 ->", safe_predict(m, [2.0, 1.6]))
print("scenario 3 ->", safe_predict(m, [2.0, float("nan"), 0.2]))

# why not a bare except: it would also swallow KeyboardInterrupt/SystemExit
def bad_wrapper(f):
    try: return f()
    except: return "swallowed"                         # noqa: E722 (deliberately bad)
print("bare except swallows SystemExit:", bad_wrapper(lambda: sys.exit(1)))

# reading a traceback: the last line names the error; the lines above are the call path
import traceback
try:
    m.predict([1, 2])
except IncompatibleFeatureSizeError:
    tb = traceback.format_exc().strip().splitlines()
    print("traceback last line:", tb[-1])
